000098 | 	public void pdfControl(HttpServletRequest request,
000099 | 							HttpServletResponse response,
000100 | 							String koteidata[][],
000101 | 							Vector data,
000102 | 							int vectorCount,
000103 | 							String formatFileName,
000104 | 							int method) throws Exception{
000105 | 		FWSessionAgent agent = null;	// エージェント
000106 | 		HttpSession session = null;	// セッション
000107 | 
000108 | 		// 処理を開始します
000109 | 		while (agent == null) {
000110 | 			// セッション（HttpSession）を獲得します。
000111 | 			session = request.getSession(true);
000112 | 			if (session == null) {
000113 | 				// セッションオブジェクトは得られない場合、致命的なエラー。
000114 | 				this.returnHttpErrorResponse(response, null, "INTERNAL ERROR (session tracking error).", STATUS_ERROR);
000115 | 				return;
000116 | 			}
000117 | 
000118 | 			//--------------------------------------------------------------
000119 | 			// エージェントを獲得します。
000120 | 			// セッション単位でエージェントオブジェクトを１個ずつ持ちます。
000121 | 			//--------------------------------------------------------------
000122 | 			try {
000123 | 				// キー AGENTNAME で FWSessionAgent オブジェクトを保持しています。
000124 | 				agent = (FWSessionAgent)session.getAttribute(AGENTNAME);
000125 | 				if (agent == null) {		// 新規セッションの場合
000126 | 					synchronized (_sessionLock) {
000127 | 						// 新規に FWSessionAgent インスタンスを生成します。
000128 | 						FWLog.debug(this.getClass(), "agent new: SID=" + session.getId());
000129 | 						agent = new FWSessionAgent(session.getId(), null, null);
000130 | 					}
000131 | 
000132 | 					if (_timeout > 0) {
000133 | 						// セッションタイマーをセットします。
000134 | 						agent.setSessionTimer(_timeout, this, session);
000135 | 					}
000136 | 
000137 | 					// このセッションで作成したエージェントを保持します。
000138 | 					
000139 | 					session.setAttribute(AGENTNAME, agent);
000140 | 				} else {			// 継続セッションの場合
000141 | 					agent.stopTimer();	// タイマーを止めます。
000142 | 				}
000143 | 			} catch (FMSystemException e) {
000144 | 				throw e;
000145 | 			} catch (FMPropertyException e) {
000146 | 				int code = e.getStatusCode();
000147 | 				this.returnHttpErrorResponse(response, null, e.getMessage(), code);
000148 | 				if (session != null) {
000149 | 					session.invalidate();
000150 | 				}
000151 | 				return;
000152 | 			} catch (IllegalStateException e) {
000153 | 				if (session != null) {
000154 | 					session.invalidate();
000155 | 				}
000156 | 				agent = null;
000157 | 				continue;
000158 | 			}
000159 | 
000160 | 			synchronized (agent) {
000161 | 				// エージェントを獲得・ロックしたので、セッションの正当性を再確認します。
000162 | 				if (agent != (FWSessionAgent)session.getAttribute(AGENTNAME)) {
000163 | 					throw new IllegalStateException();
000164 | 				}
000165 | 				FMResponse result = null;	// オーバレイの結果
000166 | 				//boolean canOverlay = false;	// オーバレイの準備ができたかどうか
000167 | 
000168 | 				try {
000169 | 					// request 中のパラメータを読みこみます。
000170 | 					agent.parseParameters(request);
000171 | 
000172 | 					if(!agent.isCallback()) {
000173 | 						agent.clear();		// 既存Jobのクリア(temp削除)
000174 | 						agent.setFMParameters(koteidata,data,vectorCount,formatFileName);
000175 | 					}
000176 | 				} catch (Exception e) {
000177 | 					throw e;
000178 | 				}
000179 | 
000180 | 				//---------------------------------------------------------
000181 | 				// オーバレイの実行
000182 | 				//---------------------------------------------------------
000183 | 				try {
000184 | 					//---------------------------------------------------------
000185 | 					// Internet Explorer の変な動作に対応するための処理
000186 | 					//---------------------------------------------------------
000187 | 					if (method == FCW_GET && agent.isCallback()) {
000188 | 						//---------------------------------------------------------
000189 | 						// GET リクエストで、かつ、プログラムが発行したコールバックである場合。
000190 | 						// セッションで蓄えておいたレスポンスを再度返します。
000191 | 						//---------------------------------------------------------
000192 | 						result = agent.getLastResponse();
000193 | 						if (result == null) {
000194 | 							throw new FMPrintException("Session may have timed out.", STATUS_ERROR);
000195 | 						}
000196 | 					} else {
000197 | 						// 明示的なオーバレイ実行命令があった
000198 | 						if (agent.canOverlay()) {
000199 | 							result = agent.overlay();
000200 | 							if (result == null) {		// 使用できるコンポーザがありません。
000201 | 								throw new FMPrintException("Request failed because no composer is available at this time. Call system manager.", STATUS_ERROR);
000202 | 							}
000203 | 						} else {
000204 | 							// オーバレイを実施できるだけのパラメータがそろっていない。
000205 | 							String msg = agent.getMessage();
000206 | 							throw new FMPropertyException(msg, STATUS_ERROR);
000207 | 						}
000208 | 					}
000209 | 				} catch (FMPrintException e) {
000210 | 					int code = e.getStatusCode();
000211 | 					this.returnHttpErrorResponse(response, null, e.getMessage(), code);
000212 | 					agent.startTimer();	// startTimer() します。
000213 | 					return;
000214 | 				} catch (FMSystemException e) {
000215 | 					throw e;
000216 | 				} catch (FMPropertyException e) {
000217 | 					int code = e.getStatusCode();
000218 | 					this.returnHttpErrorResponse(response, null, e.getMessage(), code);
000219 | 					agent.startTimer();	// startTimer() します。
000220 | 					return;
000221 | 				}
000222 | 				
000223 | 				//---------------------------------------------------------
000224 | 				// 結果の処理
000225 | 				//---------------------------------------------------------
000226 | 				try {
000227 | 					this.returnHttpResponse(response, agent, result, method);
000228 | 				} catch (FMSystemException e) {
000229 | 					throw e;
000230 | 				} catch (Exception e) {
000231 | 					throw e;
000232 | 				}
000233 | 				agent.startTimer();
000234 | 				return;	// while を抜ける
000235 | 			} // synchronized (agent)
000236 | 		} /* while */
000237 | 	}
