000046 | 	public void execute(String sql) throws SQLException{
000047 | 
000048 | 		Statement stmt = null;
000049 | 		ResultSet rs = null;
000050 | 
000051 | 		try {
000052 | 			stmt = getConnection().createStatement();
000053 | 			rs = stmt.executeQuery(sql);
000054 | 
000055 | 			//ＳＱＬ実行が正常終了したら、debug ログ出力
000056 | 			if(FWLog.isDebug()){
000057 | 				FWLog.debug(this.getClass(), sql);
000058 | 			}
000059 | 
000060 | 			setList(convertResultSetToList(rs));
000061 | 
000062 | 			if(getList() != null){
000063 | 				setCount(getList().size());
000064 | 			}
000065 | 
000066 | 		} catch (SQLException e) {
000067 | 			FWLog.error(sql);
000068 | 			throw e;
000069 | 
000070 | 		} finally {
000071 | 			if (rs != null) rs.close();
000072 | 			if (stmt != null) stmt.close();
000073 | 			rs = null;
000074 | 			stmt = null;
000075 | 		}
000076 | 	}
