000078 | 	/**
000079 | 	 * 
000080 | 	 * ResultSetをList(Map)の配列に変換する。
000081 | 	 * 
000082 | 	 * @param	rs	ResultSet
000083 | 	 * @return ls	変換されたList(Map)形式のデータ
000084 | 	 */
000085 | 	private List convertResultSetToList(ResultSet rs) throws SQLException{
000086 | 
000087 | 		List ls = new ArrayList();
000088 | 			
000089 | 		while (rs.next()) {
000090 | 
000091 | 			Map map = new HashMap();
000092 | 			ResultSetMetaData rsmd = rs.getMetaData();
000093 | 
000094 | 			for(int i=1; i <= rsmd.getColumnCount(); i++){
000095 | 				String name = rsmd.getColumnName(i);
000096 | 				String str = rs.getString(name);
000097 | 
000098 | 				if(str == null){
000099 | 					map.put(name,"");
000100 | 				} else {
000101 | 					map.put(name,str.trim());
000102 | 				}
000103 | 			}
000104 | 
000105 | 			ls.add(map);
000106 | 		}
000107 | 
000108 | 		return ls;
000109 | 	}
